    [42, "modern", "해방 이후 주요 사건 순서", 2, "중", "(마)", "modern", 6, "친애하는 메논 박사 남북 지도자 회담에 관하여 귀하와 귀 위원단에게 우리의 의견과 각서를 이미 제출한 바이어니와 우리는 가급적 우리 양인의 명의로 남에서 이에 찬동하는 제 정당의 대표 회담을 소…", 2],
    [43, "modern", "각 정부의 통일 노력", 3, "중상", "민족 자존과 통일 번영을 위한 7·7 선언을 발표하였다.", "modern", -1, "제5차 남북 고위급 회담에서 서명된 합의서는 남과 북이 오랜 단절과 대립을 청산하여 상호 신뢰를 바탕으로 이 땅에, 평화의 질서를 구축하고 교류 협력을 통해 민족의 화해와 공동 번영을 이루어가기…", 2],
    [44, "modern", "현대의 주요 사건", 2, "중", "평화 통일론을 주장한 진보당의 조봉암이 처형되었다.", "modern", 2, "오늘 미합중국 존 포스터 덜레스 국무 장관과 우리나라 변영태 외무 장관 사이에 상호 방위 조약이 체결되었습니다. 이로써 양국은 우호 관계를 바탕으로 한국에 대한 공산주의자들의 침공에 맞서 나란히…", 2],
    [45, "modern", "대한민국 개헌사", 2, "상", "(가) - 대통령의 국회의원 1/3 추천 조항을 담고 있다.", "modern", 0, "(가) 제39조 ① 대통령은 통일 주체 국민 회의에서 토론 없이 무기명 투표로 선거한다. 제47조 대통령의 임기는 6년으로 한다.", 2],
    [46, "modern", "각 정부 시기의 사실", 3, "하", "경제 협력 개발 기구(OECD) 회원국이 되었다.", "modern", 9, "오늘 내린 긴급 재정 경제 명령은 명실상부한 금융 실명제에 대한 국민의 열망을 반영하고 있습니다. 정부는 금융 외환 시장의 어려움을 극복하기 위해 국제 통화 기금에 유동성 조절 자금 지원을 요청…", 1],
    [47, "modern", "각 정부 시기의 사실", 1, "특", "진실·화해를 위한 과거사 정리 기본법이 제정되었다.", "modern", -1, "시사 토크지난 3월 정부는 호주제 폐지를 내용으로 하는 법률을 공포하였습니다. 어떤 변화가 예상되나요?", 3],
    [48, "modern", "시대별 사회 시책과 제도", 2, "하", "㉤ - 구제도감을 두어 백성을 구호하였다.", "modern", 10, "이는 저소득층에 대한 국가의 책임을 강화하는 사회 보장 제도로의 전환을 의미한다. 오늘날 사회 보장 제도는 민생 안정을 위한 역사 속 사회 시책에서도 그 뿌리를 찾아볼 수 있다.", 2],
    [49, "modern", "각 정부 시기의 사실", 3, "중상", "국가 인권 위원회가 출범하였다.", "modern", 10, "신문 제△△호 ○○○○년 ○○월 ○○일 제17회 FIFA 한일 월드컵 개막식이 열리다제17회 FIFA 한일 월드컵 개막식이 어제 저녁 서울 월드컵 경기장에서 성공적으로 열렸다. 오후 7시 25분…", 2],
    [50, "modern", "지역사", 2, "중", "ㄱ, ㄷ", "modern", -1, "달구벌 (가) 의 2·28 민주 운동을 기념하는 의미를 담은 228번 버스가 5·18 민주화 운동이 일어난 빛고을 (나) 에서 5월 18일부터 운행됩니다. 대한민국 민주주의의 역사를 공유하는 달…", 2]
