    [40, "colonial", "일제 강점기 농민 운동", 2, "상", "전국 단위 조직인 조선 농민 총동맹이 결성되었어요.", "colonial", -1, "지주가 소작인회에 기본금 2천 원을 기증할 것이 자료는 전라남도 신안군(당시 무안군)의 한 섬에서 발생한 사건의 결과로, 소작인회 대표와 지주 문재철 사이에 맺어진 화해 조건입니다. 소작인들은…", 3],
    [41, "colonial", "일제 강점기 국어 연구와 한글 보급", 2, "중상", "조선말(우리말) 큰 사전 편찬을 추진하였다.", "colonial", 11, "", 3],
    [42, "colonial", "일제 강점기의 문화", 2, "하", "나운규의 영화 아리랑이 상영되었습니다.", "colonial", -1, "자본주의적 소비 문화의 상징인 백화점이 도심에 들어섰습니다. 이것은 잡지 ‘별건곤’에 실린 삽화로, 서양식 복장을 한 ‘모던 걸’, ‘모던 보이’를 풍자한 것입니다.", 1],
    [43, "colonial", "일제 강점기 무장 투쟁", 3, "하", "미국과 연계하여 국내 진공 작전을 준비하였다.", "colonial", 9, "사료로 만나는 여성 독립운동사[해설] 이 사료는 『광복』에 실린 지복영의 글 중 일부이다. 그녀는 1940년 9월, 충칭에서 자신의 아버지 지청천을 총사령으로 하는 (가)이/가 창설될 때 오광심…", 2],
    [44, "colonial", "일제의 식민지 지배 정책", 3, "중", "애국반을 조직하여 한국인의 생활을 통제하였다.", "colonial", -1, "", 1],
    [45, "modern", "광복 이후 대한민국 정부 수립 과정", 2, "중상", "우리나라 최초의 보통 선거인 5·10 총선거가 실시되었다.", "modern", 6, "지금 이때 나의 단일한 염원은 3천만 동포와 손을 잡고 통일된 조국, 독립된 조국의 달성을 위하여 공동 분투하는 것뿐이다. 이 육신을 조국이 요구한다면 당장에라도 제단에 바치겠다.", 3],
    [46, "modern", "대한민국 각 정부 시기의 사건", 3, "중상", "한미 상호 방위 조약이 체결되었다.", "modern", 2, "이 사진은 6·25 전쟁 중 부산 임시 국회에서 개헌안을 표결하는 장면입니다. 정부는 부산 일대에 계엄을 선포하고 야당 의원들이 탄 통근 버스를 강제로 연행하는 등 공포 분위기를 조성하였습니다.", 2],
    [47, "modern", "대한민국 각 정부 시기의 사건", 3, "중상", "긴급 조치 철폐 등을 요구하는 3·1 민주 구국 선언이 발표", "modern", -1, "", 2],
    [48, "modern", "현대의 민주화 운동", 3, "중", "5년 단임의 대통령 직선제 개헌을 이끌어냈다.", "modern", 0, "", 1],
    [49, "modern", "대한민국 각 정부 시기의 활동", 1, "특", "거창 사건 등 관련자의 명예 회복에 관한 특별 조치법이 제", "modern", 7, "신문제△△호 ○○○○년 ○○월 ○○일 군대 내 사조직 ‘하나회’ 청산 매듭어제 단행된 군 장성 정기 인사를 통해 하나회 회원으로 알려진 중장급 이상 장성 전원이 보직 해임되었다. 이번 인사는 문…", 3],
    [50, "colonial", "지역사", 2, "중", "김만덕이 흉년에 굶주린 백성을 구제한 기록을 살펴본다.", "colonial", -1, "(가) 여행 정보 안내맞춤 여행 추천선택해 주세요테마 휴식/힐링 역사 탐방 액티비티다양한 성향을 기반으로 개인별 최적의 여행지를 추천해 드립니다.", 2]
